\label{thm:main2}
Let $\phi(\lambda)=\lambda^{\alpha}$ for $\alpha \in \left(\frac{1}{2},1\right)$. Let also, for any $h \in \operatorname{\mathbb{R}}$, $A \in \operatorname{\mathcal{B}}(\operatorname{\mathbb{R}})$ and $w \ge 0$
\begin{align}\label{eq:K}
\widetilde{\mathcal{K}}(A,h)=\int_0^{+\infty}\mathds{1}_A(s)p(s,h)\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds \qquad \mathcal{K}(d\tau,dh)=\widetilde{\mathcal{K}}(d\tau,h)dh
\end{align}
and
\begin{equation*}
    \mathcal{K}_w(A)=\begin{cases}
    \displaystyle \frac{\mathcal{K}(A \cap (\operatorname{\mathbb{R}} \times [w,+\infty)))}{\mathcal{K}(\operatorname{\mathbb{R}} \times [w,+\infty))} & w>0\\[7pt]
    \delta_{(0,0)}(A) & w=0.
    \end{cases}
\end{equation*}
Then
\begin{equation*}
q_\star(t,x,0)=q(T-t,x)
\end{equation*}
and, for $w>0$ and any $v<t-w$,
\begin{multline}\label{eq:possoj}
q_\star(t,x,w)=\left(xe^{-\frac{t-v-w}{2}}-K\right)_+\mathcal{K}_w(x;\operatorname{\mathbb{R}}^d \times [w+T-t,\infty))\\
    +\int_{\operatorname{\mathbb{R}} \times [w,w+T-t)}\!\!\!\!\!\!\! q(T-t+w-\tau,\log(x)+y+t-w+\tau-v)\mathcal{K}_w(d\tau,dy),
\end{multline}
where $q$ is the unique solution of
\begin{equation}\label{eq:BSUnder}
    \begin{cases}
        (\partial_t-G)^\alpha q(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q(0,x) \\
        q(0,x)=(x-K)_+\\
        q \in \operatorname{\mathcal{C}}_{0, {\rm loc}}(\operatorname{\mathbb{R}}_0^+).
    \end{cases}
\end{equation}

Notice that (\ref{eq:possoj}) is a formula that determines the value of $q_\star$ uniquely for positive sojourn time. Indeed, the only quantity that is involved is the function $q$ which is related to the value of $q_\star$ on renewal states, i.e. for zero sojourn time, which is the unique solution with at most power growth at $0$ and $\infty$ of the fully nonlocal Black-Scholes equation (\ref{eq:BSUnder}). This is also underlined by the fact that (\ref{eq:possoj}) can be rewritten as
\begin{multline}\label{eq:possoj2}
q_\star(t,x,w)=\left(xe^{-\frac{t-v-w}{2}}-K\right)_+\mathcal{K}_w(x;\operatorname{\mathbb{R}}^d \times [w+T-t,\infty))\\
    +\int_{\operatorname{\mathbb{R}} \times [w,w+T-t)}\!\!\!\!\!\!\! q_\star(t-w+\tau,\log(x)+y+t-w+\tau-v,0)\mathcal{K}_w(d\tau,dy),
\end{multline}
that only involves the function $q_\star(t,x,0)$, which is given by the solution of (\ref{eq:BSUnder}).{We remark that $(x-K)_+$ appears as an initial condition in (\ref{eq:BSUnder}) but, given that the fair price of our call option at time $t>0$ is $q_\star(t,x,w)$, then 
    \begin{align}
        (x-K)_+=q(0,x)  \, = \, q_\star (T,x,0)
    \end{align}
and thus $(x-K)_+$ is the usual final condition for
$q_\star(\cdot,\cdot,0)$. It follows that, according to our model, the fair price at time $t>0$ of a(n) (intraday) plain vanilla call option (with zero interest rate, strike price $K$ and maturity $T>t$) can be determined by solving the initial value problem (\ref{eq:BSUnder}) then changing the variable $t \rightsquigarrow  T-t$ and finally using (\ref{eq:possoj2}).
}

\label{prop:ACqstar}
	Under the hypotheses of Theorem~\ref{thm:main2}, for all $x>0$ the function $q(\cdot,x) \in {\rm AC}(\operatorname{\mathbb{R}}_0^+)$ and its a.e. derivative $\partial_t q(\cdot,x)$ satisfies, for a.a. $t \ge 0$,
	\begin{equation}\label{eq:ACqstar}
		|\partial_t q(t,x)| \le \frac{\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{\frac{Kx}{t}}.
	\end{equation}

For any $t > 0$, let $h \in \left(-\frac{t}{2},1\right)$ and consider $D^hq(t,x)=\frac{q(t+h,x)-q(t,x)}{h}$. Then we have, by (\ref{eq:selfsim}),
\begin{equation*}
	|D^h q(t,x)| \le \int_0^1 \left|\frac{q_{\rm BS}(ts+hs,x)-q_{\rm BS}(ts,x)}{hs}\right|\frac{s^{\alpha}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)}ds.
\end{equation*}
By Lagrange theorem, we know that there exists $\xi \in [\min\{ts,ts+hs\},\max\{ts,ts+hs\}]$ such that
\begin{equation*}
	\left|\frac{q_{\rm BS}(ts+hs,x)-q_{\rm BS}(ts,x)}{hs}\right|=\left|\partial_t q_{\rm BS}(x,\xi)\right|\le  \sqrt{\frac{Kx}{8\pi \xi}} \le \sqrt{\frac{Kx}{4\pi ts}},
\end{equation*}
where we also used (\ref{eq:der5}). Hence
\begin{equation*}
	|D^hq(t,x)| \le \sqrt{\frac{Kx}{4\pi t}}\int_0^1 \frac{s^{\alpha-\frac{1}{2}}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)}ds=\frac{\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{\frac{Kx}{t}}.

\end{equation*}
The right-hand side is independent of $h$ and belongs to $L^1(0,T)$ for all $T>0$, thus we can argue as in Proposition~\ref{prop:AC} and get the result.

\label{coro:diffest}
    Under the assumptions of Theorem \ref{thm:main2} we have that for all $t,x>0$
    \begin{equation*}
    \int_0^t |P_s q(t-s,x)-P_sq(t,x)|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds<\infty
    \end{equation*}
    and, for all $\lambda>\frac{3}{8}$ and $x>0$,
    \begin{equation*}
    \int_0^\infty \int_0^t e^{-\lambda t}  |P_s q(t-s,x)-P_sq(t,x)|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds\, dt<\infty.
    \end{equation*}

Fix $x>0$, and note that for $0 <s<t$,
    \begin{multline}
     \left|   q (t-s,x) - q (t,x) \right| \leq \int_0^s \left| \partial_t q(t-\tau,x) \right| d\tau \\
     \leq  \frac{\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{Kx}\int_0^s(t-\tau)^{-1/2}d\tau
     =\frac{\Gamma\left(\alpha+\frac{1}{2}\right) s}{\pi \Gamma(\alpha)}\sqrt{\frac{Kx}{t-s}}.\label{623}
    \end{multline}
    This proves that $\left|   q (t-s,\cdot) - q (t,\cdot) \right| \in \operatorname{\mathcal{C}}_0(1/2)$. We get, by also employing Items $(1)$ and $(5)$ of Lemma \ref{lem:BSuniqueness},
    \begin{align*}
        \int_0^t &|P_s q(t-s,x)-P_sq(t,x)|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds\\
        & \le \int_0^t P_s |q(t-s,\cdot)-q(t,\cdot)|(x)\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds \\
        &\le \frac{2 \alpha \Gamma\left(\alpha+\frac{1}{2}\right) \sqrt{K}}{\pi \Gamma(\alpha)\Gamma(1-\alpha)}e^{\frac{1}{2}|\log(x)|+\frac{3}{8}t}\int_0^t s^{-\alpha}(t-s)^{-\frac{1}{2}}ds\\
        &=\frac{2 \alpha \Gamma\left(\alpha+\frac{1}{2}\right) \sqrt{K}}{\Gamma(\alpha)\Gamma\left(\frac{3}{2}-\alpha\right)\sqrt{\pi} }t^{\frac{1}{2}-\alpha}e^{\frac{1}{2}|\log(x)|+\frac{3}{8}t},
    \end{align*}
    where we also used \cite[Lemma 1.11]{ascione2023fractional}. Furthermore, for any $\lambda>\frac{3}{8}$ it holds
    \begin{align*}
        \int_0^\infty &\int_0^t e^{-\lambda t}  |P_s q(t-s,x)-P_sq(t,x)|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds\, dt \\
        &\le \frac{2 \alpha \Gamma\left(\alpha+\frac{1}{2}\right) \sqrt{K}}{\Gamma(\alpha)\Gamma\left(\frac{3}{2}-\alpha\right)\sqrt{\pi} }t^{\frac{1}{2}-\alpha}e^{\frac{1}{2}|\log(x)|}\int_0^\infty t^{\frac{1}{2}-\alpha}e^{-\left(\lambda-\frac{3}{8}\right)t}\, dt\\
        &=\frac{2 \alpha \Gamma\left(\alpha+\frac{1}{2}\right) \sqrt{K}}{\Gamma(\alpha)\sqrt{\pi} }t^{\frac{1}{2}-\alpha}e^{\frac{1}{2}|\log(x)|}\left(\lambda-\frac{3}{8}\right)^{\alpha-\frac{3}{2}}.
    \end{align*}

\label{prop:regq}
Under the assumptions of Theorem \ref{thm:main2}, the following equalities hold for all $t,x>0$:
\begin{align}
    &\partial_x q (t,x) \, = \, \frac{1}{\Gamma (\alpha)\Gamma (1-\alpha)}\int_0^1 \partial_x q_{\rm BS} (\tau t, x) \, \tau^{\alpha-1} (1-\tau)^{-\alpha} d\tau , \label{derstar1}\\
    & \partial_x^2 q(t,x) \, = \, \frac{1}{\Gamma (\alpha)\Gamma (1-\alpha)}\int_0^1 \partial_x^2 q_{\rm BS} (\tau t, x) \, \tau^{\alpha-1} (1-\tau)^{-\alpha} d\tau , \label{derstar2}\\
    & G q (t,x) \, = \, \frac{1}{\Gamma (\alpha)\Gamma (1-\alpha)}\int_0^1 G q_{\rm BS} (\tau t, x) \, \tau^{\alpha-1} (1-\tau)^{-\alpha} d\tau . \label{derstar3}
\end{align}
Furthermore $q(t,\cdot) \in \operatorname{\mathcal{C}}_0(1)$, $\partial_x q(t,\cdot) \in \operatorname{\mathcal{C}}_0(0)$ and $Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0(1/2)$ for all $t>0$, where
\begin{align}
|q(t,x)| &\le e^{|\log(x)|} \label{eq:est1q}\\
|\partial_x q(t,x)| &\le 1 \label{eq:est2q}\\
|G q(t,x)| & \le  \sqrt{\frac{K x}{2 t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)} \label{eq:est3q}.
\end{align}
In particular, $q \in \operatorname{\mathcal{C}}_{0, {\rm loc}}(\operatorname{\mathbb{R}}_0^+)$.

By (\ref{eq:qspecial}) and (\ref{eq:der3.5}) we already know that $q \in \operatorname{\mathcal{C}}_0(1)$ with $[q]_1 \le 1$. Moreover, by (\ref{eq:der4}), we know that we can apply the dominated convergence theorem to take the derivative inside the integral sign in (\ref{eq:qspecial}) and then using (\ref{eq:selfsim}), getting (\ref{derstar1}). Furthermore, (\ref{eq:der4}) also implies that $\partial_x q(t,\cdot) \in \operatorname{\mathcal{C}}_0(0)$ with $[\partial_x q(t,\cdot)]_0 \le 1$. 

To argue with the second derivative, fix $a > 0$ and notice that for all $x \ge a$ it holds, by (\ref{eq:der6}),
\begin{align*}
    \int_0^1 \left|\partial_x^2 q_{\rm BS}(ts,x)\right|\frac{s^{\alpha-1}(1-s)^{-\alpha}}{\Gamma(1-\alpha)\Gamma(\alpha)}ds &\le \sqrt{\frac{K}{8\pi a^3 t}}\int_0^1 \frac{s^{\alpha-\frac{3}{2}}(1-s)^{-\alpha}}{\Gamma(1-\alpha)\Gamma(\alpha)}ds\\
    &=\frac{1}{2\pi}\sqrt{\frac{K}{2a^3 t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{\Gamma(\alpha)}<\infty,
\end{align*}
since $\alpha>\frac{1}{2}$. Hence, by dominated convergence, we get (\ref{derstar2}) and finally, multiplying both sides of (\ref{derstar2}) by $\frac{x^2}{2}$, we also get (\ref{derstar3}). Finally, notice that (\ref{derstar3}) and (\ref{eq:der5}) imply that $Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0(1/2)$ for all $t>0$ and in particular
\begin{equation*}
\left|Gq(t,x)\right| \le \sqrt{\frac{K x}{8\pi t}}\int_0^1 \frac{s^{\alpha-\frac{3}{2}}(1-s)^{-\alpha}}{\Gamma(1-\alpha)\Gamma(\alpha)}ds=\sqrt{\frac{K x}{2 t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}.
\end{equation*}

Notice that Proposition \ref{prop:ACqstar}, Corollary \ref{coro:diffest}, (\ref{derstar1}), (\ref{eq:est1q}) and (\ref{eq:est2q}) hold for any $\alpha \in (0,1)$. The condition $\alpha>1/2$ comes into play only for (\ref{derstar2}), (\ref{derstar3}) and (\ref{eq:est3q}). However, it is worth highlighting that, using a finer estimate in place of (\ref{eq:der6}), it is possible to prove that (\ref{derstar2}) and (\ref{derstar3}) still hold for all $t, x>0$ with $x \not = K$ if $\alpha \le 1/2$. However, notice that, for $h \in [0,1]$, by Lagrange's theorem,
\begin{align*}
\frac{\partial_x q_{\rm BS}(ts,K+h)-\partial_xq_{\rm BS}(ts,K)}{h}&=\partial_x^{2}q_{\rm BS}(ts,\xi)\\
&=\sqrt{\frac{K}{2\pi ts \xi^3}}\exp\left(-\frac{4\log^2(\xi/K)+t^2s^2}{8ts}\right)\\
&\ge \sqrt{\frac{K}{2\pi ts (K+1)^3}}\exp\left(-\frac{4\log^2\left(1+\frac{h}{K}\right)+t^2s^2}{8ts}\right)
\end{align*}
where $\xi \in [K,K+h]$. Hence, by (\ref{derstar1}), we have
\begin{align*}
&\frac{\partial_x q(t,K+h)-\partial_xq(t,K)}{h}\\
&\qquad =\int_0^1 \frac{\partial_x q_{\rm BS}(ts,K+h)-\partial_xq_{\rm BS}(ts,K)}{h}\frac{s^{\alpha-1}(1-s)^{-\alpha}}{\Gamma(\alpha) \Gamma(1-\alpha)}\, ds\\
&\qquad \ge \frac{\sqrt{K}}{\sqrt{2\pi t(K+1)^3}}\int_0^1 \exp\left(-\frac{4\log^2\left(1+\frac{h}{K}\right)+t^2s^2}{8ts}\right) \frac{s^{\alpha-\frac{3}{2}}(1-s)^{-\alpha}}{\Gamma(\alpha) \Gamma(1-\alpha)}\, ds.
\end{align*}
Taking the limit as $h \to 0^+$ we have, as a consequence of the monotone convergence theorem,
\begin{multline*}
\lim_{h \to 0^+}\frac{\partial_x q(t,K+h)-\partial_xq(t,K)}{h}\\
\ge \frac{\sqrt{K}}{\Gamma(\alpha) \Gamma(1-\alpha)\sqrt{2\pi t(K+1)^3}}\int_0^1 \exp\left(-\frac{ts}{8}\right) s^{\alpha-\frac{3}{2}}(1-s)^{-\alpha}\, ds=\infty,
\end{multline*}
if $\alpha \le \frac{1}{2}$. Hence, in such a case, $q(t,\cdot)$ cannot admit a second order derivative in $x=K$. Suppose that we have already shown that $q$ is solution of (\ref{eq:BSUnder}), then this lack of parabolic smoothing is also common in time-nonlocal equations, see for instance \cite[Proposition 3.3]{ascione2024time}.

Under the assumptions of Theorem \ref{thm:main2} it holds, for all $t,x>0$,
    \begin{equation*}
        \int_0^t |P_sq(t,x)-q(t,x)|\, \nu_\alpha(ds)<\infty,
    \end{equation*}
    and, for all $x>0$ and $\lambda>\frac{3}{8}$,
    \begin{equation*}
        \int_0^{\infty}\int_0^t e^{-\lambda t}|P_sq(t,x)-q(t,x)|\, \nu_\alpha(ds)\, dt<\infty
    \end{equation*}
    where $\nu_\alpha(ds)$ is the L\'evy measure corresponding to $\phi(\lambda) = \lambda^\alpha$, $\alpha \in (1/2,1)$, i.e., \begin{align}
        \nu_\alpha(ds)= \alpha s^{-\alpha-1}/\Gamma(1-\alpha)ds.
        \label{stablev}
    \end{align}

By Proposition \ref{prop:regq} we know that $q(t,\cdot) \in \operatorname{\mathcal{C}}_0$ hence we can write
\begin{equation*}
P_sq(t,x)-q(t,x)=\int_0^s GP_\tau q(t,x) d\tau.
\end{equation*}
Recalling that, still by Proposition \ref{prop:regq}, $\partial_x q(t,\cdot), Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0$, by Item $(3)$ of Lemma \ref{lem:BSuniqueness} we have
\begin{equation}\label{eq:Psestq}

{P_sq(t,x)-q(t,x)=\int_0^s P_\tau G q(t,x) d\tau.}
\end{equation}
In particular, $Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0(1/2)$ and, by (\ref{eq:est3q})
\begin{equation*}
    [Gq(t,\cdot)]_{1/2} \le \sqrt{\frac{K}{2 t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}.
\end{equation*}
Hence, by Item $(5)$ of Lemma \ref{lem:BSuniqueness} we get that $P_\tau Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0(1/2)$ with
\begin{equation*}
    [P_\tau Gq(t,\cdot)]_{1/2} \le \sqrt{\frac{2K}{ t}}e^{\frac{3}{8}\tau}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}.
\end{equation*}
Using this into (\ref{eq:Psestq}) we have
\begin{align*}
    \left|P_sq(t,x)-q(t,x)\right|& {\le}\int_0^s \left|P_\tau Gvq(t,x)\right| d\tau \le \sqrt{\frac{2K}{ t}}e^{\frac{1}{2}|\log(x)|}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}\int_0^s e^{\frac{3}{8}\tau} \, d\tau\\
    &\le \sqrt{\frac{2K}{ t}}e^{\frac{1}{2}|\log(x)|}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}s}s.
\end{align*}
Integrating the latter against $\nu_\phi$, we have
\begin{align*}
\int_0^t \left|P_sq(t,x)-q(t,x)\right|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}ds &\le \sqrt{\frac{2K}{ t}}e^{\frac{1}{2}|\log(x)|}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}\int_0^t e^{\frac{3}{8}s}\frac{\alpha s^{-\alpha}}{\Gamma(1-\alpha)}\, ds\\
&\le e^{\frac{1}{2}|\log(x)|}\frac{\alpha \Gamma\left(\alpha-\frac{1}{2}\right) \sqrt{2K}}{2\pi \Gamma(\alpha)\Gamma(2-\alpha)}e^{\frac{3}{8}t}t^{\frac{1}{2}-\alpha}.
\end{align*}
Finally, integrating the latter against $e^{-\lambda t}$ for $\lambda>\frac{3}{8}$ we get
\begin{align*}
\int_0^{\infty} \int_0^t &e^{-\lambda t}\left|P_sq(t,x)-q(t,x)\right|\frac{\alpha s^{-\alpha-1}}{\Gamma(1-\alpha)}\, ds\, dt \\
&\le e^{\frac{1}{2}|\log(x)|}\frac{\alpha \Gamma\left(\alpha-\frac{1}{2}\right)\sqrt{2K}}{2\pi \Gamma(\alpha)\Gamma(2-\alpha)}\int_0^{\infty}e^{-\left(\lambda-\frac{3}{8}\right)t}t^{\frac{1}{2}-\alpha}\, dt\\
&=e^{\frac{1}{2}|\log(x)|}\frac{\alpha \Gamma\left(\alpha-\frac{1}{2}\right)\sqrt{2K}}{2\pi \Gamma(\alpha)\Gamma(2-\alpha)}\left(\lambda-\frac{3}{8}\right)^{\alpha-\frac{3}{2}}\Gamma\left(\frac{3}{2}-\alpha\right).
\end{align*}

Under the assumptions of Theorem \ref{thm:main2} for all $x,\lambda>0$ it holds
    \begin{equation*}
    \int_0^\infty e^{-\lambda t} \overline{\nu}_\alpha(t) |q(t,x)|\, dt <\infty,
    \end{equation*}
    where $\bar{\nu}_\alpha(t)$ is the tail of (\ref{stablev}).

Since $\overline{\nu}_\phi(t)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}$, we just use {the inequality} (\ref{eq:est1q}) to get



    \textcolor{black}{\begin{align*}
    \int_0^\infty e^{-\lambda t} \frac{t^{-\alpha}}{\Gamma(1-\alpha)} |q(t,x)|\, dt \le \frac{e^{|\log(x)|}}{\Gamma(1-\alpha)}\int_0^\infty t^{-\alpha}e^{-\lambda t}dt=\frac{e^{|\log(x)|}}{\lambda^{1-\alpha}}.
    \end{align*}}

In view of the results in Subsection \ref{regstar}, we know by Theorem \ref{thm:integrability2} that $(\partial_t-G)^\alpha q(t,x)$ is well-defined for all $x,t>0$. Moreover, for any $x>0$ we know by Theorem \ref{thm:Lapinside2} that $(\partial_t-G)^\alpha q(\cdot,x)$ admits Laplace transform for any $\lambda>\frac{3}{8}$.
    We divide the proof into two parts. First we check that for all $x>0$ and $\lambda>\frac{3}{8}$ we have
\begin{equation}\label{eq:Laptranseq}
\int_0^\infty e^{-\lambda t}(\partial_t-G)^\alpha q(t,x)dt=\lambda^{\alpha-1}(x-K)_+,
\end{equation}
which is the first equation in  (\ref{eq:BSUnder}) after taking the Laplace transform in the $t$ variable on both sides. Then we use this to prove that
\begin{align}
    (\partial_t-G)^\alpha q(t,x) = \frac{t^{-\alpha}}{\Gamma(1-\alpha)} q(0,x).
\end{align}
We begin with (\ref{eq:Laptranseq}).
Consider $x>0$, $\lambda>\frac{3}{8}$ and denote
  \begin{equation*}
  \widetilde{q}(\lambda,x)=\int_0^\infty e^{-\lambda t}q(t,x) \, dt.
  \end{equation*}
  Let us first evaluate an alternative formula for $\widetilde{q}$. Set $u_K(x)=(x-K)_+$ and notice that, by (\ref{eq:qspecial}), we get
    \begin{align}
    \widetilde{q}(\lambda,x) \, = \, &\frac{1}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty e^{-\lambda t}\int_0^t s^{\alpha-1}(t-s)^{-\alpha}q_{\rm BS}(s,x)\, ds \, dt \notag \\
    = \, & \frac{\lambda^{\alpha -1}}{\Gamma(\alpha)} \int_0^{+\infty} e^{-\lambda s} s^{\alpha-1} q_{\rm BS}(s,x) \, ds \notag \\
    = \, & \frac{\lambda^{\alpha -1}}{\Gamma (\alpha)} \int_0^{+\infty} e^{-\lambda s} s^{\alpha -1} P_su_K(x) \, ds, \label{qtildastar}
    \end{align}
    where, in the first step, we used the convolution Theorem for Laplace transform (e.g., \cite[Proposition 1.6.4]{arendt2011vector}) and then we applied Tonelli's theorem since $q_{\rm BS}$ is non-negative.  As a consequence of (\ref{eq:postFubini}), we have that                                                                                                              
\begin{align}
		\int_0^\infty e^{-\lambda t} & \left(   \partial_t -G \right) ^\alpha q(x,t) \, dt \, \nonumber\\= \,
  & -\int_0^\infty \int_0^\infty e^{-\lambda t} (P_s q(t-s,x)\mathds{1}_{(0,t]}(s)-q(t,x))\, dt \,\nu_\alpha(ds) \nonumber\\
  \, = \, & -\int_0^\infty \left( \int_s^\infty  \int_0^\infty e^{-\lambda t}q(t-s,y)p_{\rm GBM}(s,y;x)\, dy \, dt - \widetilde{q}(\lambda,x)\right) \, \nu_\alpha (ds) \nonumber\\
  \, = \, & -\int_0^\infty \left( e^{-\lambda s}\int_0^\infty    \widetilde{q} (\lambda,y)p_{\rm GBM}(s,y;x)\, dy - \widetilde{q}(\lambda,x)\right) \, \nu_\alpha (ds)\nonumber
  \\
  \, = \, & -\int_0^\infty \left( e^{-\lambda s}P_s(\widetilde{q} (\lambda,\cdot))(x) - \widetilde{q}(\lambda,x)\right) \, \nu_\alpha (ds), \nonumber
	\end{align}
 where in the third equality we used again Tonelli's theorem to exchange the order of the integrals (since $q$ and $p_{\rm GBM}$ are non-negative) after having made explicit the action of the operator $P_s$ in the second step.  Now we can replace $\widetilde{q}$ in the previous identity by making use of (\ref{qtildastar}). To do this, we first observe that
 \begin{align}
     P_s  \left(  \widetilde{q} (\lambda, \cdot) \right)  (x) \, = \, & \frac{\lambda^{\alpha-1}}{\Gamma(\alpha)} \int_0^{+\infty}\int_0^{+\infty} e^{-\lambda \tau} \tau^{\alpha-1} P_\tau u_K(y) p_{\rm GBM}(s, y;x) d\tau \, dy \notag \\
     = \, & \frac{\lambda^{\alpha-1}}{\Gamma(\alpha)} \int_0^{+\infty} e^{-\lambda \tau} \tau^{\alpha-1} P_{s+\tau} u_K(x) \, d\tau
 \end{align}
 and then we have
 \begin{align}
		&\int_0^\infty e^{-\lambda t}  \left(   \partial_t -G \right) ^\alpha q(x,t) \, dt \notag \\  = \, &-\frac{\alpha\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty} \tau^{\alpha-1}s^{-\alpha-1}\left( e^{-\lambda (s+\tau)} P_{s+\tau} u_K(x) \,  -   e^{-\lambda \tau} P_{\tau} u_K(x) \,  \right)d\tau\, ds \notag \\
  = \, & -\frac{\alpha\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty} \tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda \tau}P_\tau\left( e^{-\lambda s} q_{\rm BS}(s,x)\,  -  u_K(x) \,  \right)d\tau\, ds,
  \end{align}
 where we used the fact that $P_\tau$ is a semigroup action and the explicit form of $\nu_\alpha(\cdot)$ given in (\ref{stablev}). However, if we observe that 
  \begin{align}
     e^{-\lambda s} q_{\rm BS}(s,x)\,  -  u_K(x) \, = \, & \int_0^s \partial_w e^{-\lambda w} q_{\rm BS} (w,x) \, dw \notag \\ \,& \int_0^s e^{-\lambda w}  \left(  \partial_w q_{\rm BS}(w,x) - \lambda q_{\rm BS} (w,x) \right)  \, dw \notag \\
     = \, & \int_0^s e^{-\lambda w}   \left(  G  - \lambda   \right)  \,  q_{\rm BS}(w,x) \, dw 
 \end{align}
and we explicitly write the integral in $P_\tau$, we get
 \begin{align}
     &\int_0^\infty e^{-\lambda t}  \left(   \partial_t -G \right) ^\alpha q(x,t) \, dt \notag \\  = \, & -\frac{\alpha\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty}\int_0^{+\infty} \int_0^s\tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)}  \left(  G  - \lambda   \right)  \,  q_{\rm BS}(w,y) \,  p_{\rm GBM}(\tau,y;x) \, dw  \, dy \, d\tau\, ds \label{eq:preFub}.


 \end{align}

We want to use Fubini's theorem to change the order of the integrals. To do this, we notice that (\ref{eq:der3}) implies $G q_{BS} \ge 0$ and then
 \begin{align}
 &   \int_0^{+\infty}\int_0^{+\infty}\int_0^{+\infty} \int_0^s \tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)} \left| (G-\lambda) q_{\rm BS} (w,y) \right| p_{\rm GBM} (\tau, y;x) \, dw \, dy \, d\tau \, ds \notag \\ &\leq \int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \int_0^{+\infty} \tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}(G+\lambda)q_{\rm BS}(w,y) p_{\rm GBM} (\tau, y;x) \, dy \, dw  \, d\tau \, ds\\
 &=\int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}P_\tau (G+\lambda)q_{\rm BS}(w,x) \, dw  \, d\tau \, ds



 \label{bound646}
 \end{align}
Since $q_{\rm BS}(t,\cdot) \in \operatorname{\mathcal{C}}_0$, $\partial_x q_{\rm BS} \in \operatorname{\mathcal{C}}_0$ and $Gq_{\rm BS} \in \operatorname{\mathcal{C}}_0$, we can exchange the operator $(G+\lambda)$ with $P_\tau$, getting
 \begin{align}
 &   \int_0^{+\infty}\int_0^{+\infty}\int_0^{+\infty} \int_0^s \tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)} \left| (G-\lambda) q_{\rm BS} (w,y) \right| p_{\rm GBM} (\tau, y;x) \, dw \, dy \, d\tau \, ds \notag \\ &\leq \int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}(G+\lambda)P_\tau q_{\rm BS}(w,x) \, dw  \, d\tau \, ds\\
 &= \int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}(G+\lambda)q_{\rm BS}(\tau+w,x) \, dw  \, d\tau \, ds,



 \label{bound6462}
 \end{align}
where we also used the fact that $P_\tau q_{\rm BS}(w,x)=P_\tau P_w u_K(x)=P_{\tau+w}u_K(x)=q_{\rm BS}(w+\tau,x)$. By (\ref{eq:der3}) we have
\begin{equation}\label{eq:control}
    Gq_{\rm BS}(\tau+w,x) \le \sqrt{\frac{Kx}{8\pi(\tau+w)}}\exp\left(-\frac{\log^2\left(\frac{x}{K}\right)}{2(\tau+w)}\right).
\end{equation}
Consider the function $r \in \operatorname{\mathbb{R}}^+ \mapsto \sqrt{r}\exp\left(-r\frac{\log^2\left(\frac{x}{K}\right)}{2}\right) \in \operatorname{\mathbb{R}}$. It is possible to check that such a function has a maximum at $r_\star=\log^{-2}\left(\frac{x}{K}\right)$ and then
\begin{equation*}
    \sqrt{r}\exp\left(-r\frac{\log^2\left(\frac{x}{K}\right)}{2}\right) \le \frac{1}{\sqrt{e}}\left|\log^{-1}\left(\frac{x}{K}\right)\right|.
\end{equation*}
Plugging the latter into (\ref{eq:control}), adding $\lambda q_{\rm BS}(\tau+w,x)$ and also using  (\ref{eq:der3.5}) we get
\begin{equation*}
    (G+\lambda)q_{\rm BS}(\tau+w,x) \le \sqrt{\frac{Kx}{8\pi e}}\left|\log^{-1}\left(\frac{x}{K}\right)\right|+\lambda e^{|\log(x)|}.
\end{equation*}
Plugging this inequality into (\ref{bound6462}) we obtain
 \begin{align}
&\int_0^{+\infty}\int_0^{+\infty}\int_0^{+\infty} \int_0^s \tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)} \left| (G-\lambda) q_{\rm BS} (w,y) \right| p_{\rm GBM} (\tau, y;x) \, dw \, dy \, d\tau \, ds \notag \\ \leq \,& \frac{1}{\lambda}\left(\sqrt{\frac{Kx}{8\pi e}}\left|\log^{-1}\left(\frac{x}{K}\right)\right|+\lambda e^{|\log(x)|}\right)\int_0^{+\infty}\int_0^{+\infty}  \tau^{\alpha-1} (1-e^{-\lambda s})s^{-\alpha-1}e^{-\lambda \tau}  \, d\tau \, ds \nonumber\\
= & \frac{1}{\lambda}\left(\sqrt{\frac{Kx}{8\pi e}}\left|\log^{-1}\left(\frac{x}{K}\right)\right|+\lambda e^{|\log(x)|}\right)\left(\int_{0}^{+\infty}\tau^{\alpha-1}e^{-\lambda \tau} \, d\tau \right)\left(\int_{0}^{+\infty}s^{-\alpha-1}(1-e^{-\lambda s}) \, ds\right)\nonumber\\
= &\frac{1}{\lambda}\left(\sqrt{\frac{Kx}{8\pi e}}\left|\log^{-1}\left(\frac{x}{K}\right)\right|+\lambda e^{|\log(x)|}\right)\frac{\Gamma(\alpha)\Gamma(1-\alpha)}{\alpha}<\infty \nonumber
\end{align}
where, in the last step, we used the integral representation of the Gamma function that
\begin{align*}
    \int_{0}^{+\infty}s^{-\alpha-1}(1-e^{-\lambda s}) \, ds = \frac{\Gamma(1-\alpha)}{\alpha} \lambda^\alpha.
\end{align*}
We can now safely use Fubini's theorem in (\ref{eq:preFub}), obtaining
 \begin{align}
     &\int_0^\infty e^{-\lambda t}  \left(   \partial_t -G \right) ^\alpha q(x,t) \, dt \notag \\  

     &=  -\frac{\alpha\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty}\int_0^{+\infty} \int_w^{+\infty}\tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)}   \left(  G  - \lambda   \right)  \,  q_{\rm BS}(w,y) \,  p_{\rm GBM}(\tau,y;x) \, ds  \, dy \, d\tau\, dw \nonumber \\
     &=  -\frac{\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty}\tau^{\alpha-1}w^{-\alpha}e^{-\lambda (\tau+w)}  P_\tau  \left(  G  - \lambda   \right)  \,  q_{\rm BS}(w,x)   \, d\tau\, dw \notag\\
     &=  -\frac{\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_0^{+\infty}\tau^{\alpha-1}w^{-\alpha}e^{-\lambda (\tau+w)}    \left(  G  - \lambda   \right)  \,  q_{\rm BS}(\tau+w,x)   \, d\tau\, dw \notag \\
     &=  -\frac{\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty   \int_w^{+\infty}(z-w)^{\alpha-1}w^{-\alpha}    \left(  G  - \lambda   \right)  \,  e^{-\lambda z} q_{\rm BS}(z,x)   \, dz\, dw \notag\\
     &=  -\frac{\lambda^{\alpha-1}}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^\infty    \left(  G  - \lambda   \right)  \,  e^{-\lambda z} q_{\rm BS}(z,x)\left(\int_0^{z}(z-w)^{\alpha-1}w^{-\alpha}   \, dw\right)\, dz \notag\\
     &= -\lambda^{\alpha-1}\int_0^\infty    \left(  G  - \lambda   \right)  \,  e^{-\lambda z} q_{\rm BS}(z,x) dz, \label{eq:tosubs}
 \end{align}
where in the third equality we used that $P_\tau q_{\rm BS} (w,y) = P_\tau P_w u_K(x) = P_{\tau+w}u_K(x) = q_{\rm BS} (\tau+w,x)$, in the fourth equality we used the change of variables $\tau=z-w$, in the fifth equality we used again Fubini's theorem and in the last equality we used the integral representation of the Beta function. Now notice that (\ref{eq:der3.5}), (\ref{eq:der4}) and (\ref{eq:der5}) guarantee that we can take the Laplace transform in the variable $t$ on both sides of the first equation of (\ref{eq:BSclass1}), leading to
\begin{equation*}
\lambda \int_0^{+\infty} e^{-\lambda z}q_{\rm BS}(z,x)dz-u_K(x)=\int_0^{+\infty} e^{-\lambda z}Gq_{\rm BS}(z,x)dz.
\end{equation*}
This equality can be rearranged to obtain
\begin{equation*}
\int_0^{+\infty} (\lambda-G)e^{-\lambda z} q_{\rm BS}(z,x)dz=u_K(x)
\end{equation*}
which, replaced into (\ref{eq:tosubs}) gives (\ref{eq:Laptranseq}).

By injectivity of the Laplace transform, we know that for all $x>0$ there exists a measurable set $\mathcal{I}_x \subset \operatorname{\mathbb{R}}^+$ such that $|\mathcal{I}_x|=0$ and for all $t \in \operatorname{\mathbb{R}}^+ \setminus \mathcal{I}_x$ one has
\begin{equation*}
    (\partial_t-G)^\alpha q(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q(0,x).
\end{equation*}
We want to prove that $\mathcal{I}_x=\varnothing$ for all $x>0$. To do this, we first show that $q$ is continuous. Indeed, let $t,x>0$ and consider a sequence $(t_n,x_n) \to (t,x)$. By (\ref{eq:qspecial}) and (\ref{eq:selfsim}) we have
\begin{equation*}
    q(t_n,x_n)=\int_0^1 q_{\rm BS}(t_ns,x_n)\frac{(1-s)^{-\alpha}s^{\alpha-1}}{\Gamma(1-\alpha)\Gamma(\alpha)}ds.
\end{equation*}
Since $x_n \to x$, there exist $0<a<b$ such that $x_n \in [a,b]$ for all $n \in \operatorname{\mathbb{N}}$ and then $|q_{\rm BS}(t_ns,x_n)| \le e^{\max\{|\log(a)|, |\log(b)|\}}$. Hence, we can use the dominated convergence theorem to get
\begin{equation*}
    \lim_{n \to +\infty}q(t_n,x_n)=\int_0^1 q_{\rm BS}(ts,x)\frac{(1-s)^{-\alpha}s^{\alpha-1}}{\Gamma(1-\alpha)\Gamma(\alpha)}ds=q(t,x).
\end{equation*}
Now we prove that for fixed $x>0$ the function $(\partial_t-G)^\alpha q(\cdot,x)$ is right-continuous. Indeed, let $t_n \downarrow t$ for some $t>0$ and observe that 
\begin{align*}
    &|(\partial_t-G)^\alpha q(t_n,x)-(\partial_t-G)^\alpha q(t,x)| \\
    &\le \frac{\alpha}{\Gamma(1-\alpha)}\int_0^t |P_sq(t-s,x)-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)| s^{-1-\alpha}ds\\
    &+\frac{\alpha}{\Gamma(1-\alpha)}\int_t^{t_n} |P_sq(t_n-s,x)-q(t_n,x)| s^{-1-\alpha}ds\\
    &+\frac{t^{-\alpha}-t_n^{-\alpha}}{\Gamma(1-\alpha)}|q(t,x)|+|q(t,x)-q(t_n,x)|\frac{t_n^{-\alpha}}{\Gamma(1-\alpha)}\\
    &:=\frac{\alpha}{\Gamma(1-\alpha)}\left(I_n(x)+J_n(x)+\frac{t^{-\alpha}-t_n^{-\alpha}}{\alpha}|q(t,x)|+|q(t,x)-q(t_n,x)|\frac{t_n^{-\alpha}}{\alpha}\right).
\end{align*}
Let us first consider $I_n(x)$. We have
\begin{align*}
    |P_sq(t-s,x)&-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)|\\
    & \le |P_sq(t-s,x)-P_sq(t_n-s,x)| + |q(t,x)-q(t_n,x)|\\
    &\le P_s|q(t_n-s,\cdot)-q(t-s,\cdot)|(x) + |q(t,x)-q(t_n,x)|
\end{align*}
Arguing as in the proof of Corollary \ref{coro:diffest}, we have that $|q(t-s,\cdot)-q(t_n-s,\cdot)| \in \operatorname{\mathcal{C}}_0(1/2)$ with $t_n-s-(t_n-t)$
\begin{equation*}
[|q(t-s,\cdot)-q(t_n-s,\cdot)|]_{1/2} \le \frac{\Gamma\left(\alpha+\frac{1}{2}\right)(t_n-t)}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}.
\end{equation*}
Hence, by Item $(5)$ of Lemma \ref{lem:BSuniqueness} we have
\begin{align*}
P_s|q(t_n-s,\cdot)-q(t-s,\cdot)|(x) \le 2\frac{\Gamma\left(\alpha+\frac{1}{2}\right)(t_n-t)}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}e^{\frac{3}{8}s+\frac{|\log(x)|}{2}}.
\end{align*}
Combining this inequality with the fact that $q$ is continuous, for fixed $s \in [0,t)$, we find
\begin{equation*}
    \lim_{n \to \infty}|P_sq(t-s,x)-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)|=0.
\end{equation*}
Hence, it is sufficient to show that we can use the dominated convergence theorem to take the limit inside the integral sign in $I_n(x)$. To do this, observe that
\begin{align}\label{eq:In0}
\begin{split}
    |P_sq(t-s,x)&-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)|\\
    & \le |P_sq(t-s,x)-P_sq(t,x)| + |P_sq(t,x)-q(t,x)|\\
    & \qquad +|P_sq(t_n-s,x)-P_sq(t_n,x)|+|P_sq(t_n,x)-q(t_n,x)|\\
    &\le P_s|q(t-s,\cdot)-q(t,\cdot)|(x) + |P_sq(t,x)-q(t,x)|\\
    & \qquad + P_s|q(t_n-s,\cdot)-q(t_n,\cdot)|(x)+|P_sq(t_n,x)-q(t_n,x)|.
    \end{split}
\end{align}
Again recall that $|q(t-s,\cdot)-q(t,\cdot)| \in \operatorname{\mathcal{C}}_0(1/2)$ with
\begin{equation*}
[|q(t-s,\cdot)-q(t,\cdot)|]_{1/2} \le \frac{\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}},
\end{equation*}
hence, by Item $(5)$ of Lemma \ref{lem:BSuniqueness},
\begin{align}
    P_s|q(t-s,\cdot)-q(t,\cdot)|(x) &\le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}e^{\frac{3}{8}t+\frac{|\log(x)|}{2}}\nonumber\\
    & \le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}} \label{eq:In1}\\
    P_s|q(t_n-s,\cdot)-q(t_n,\cdot)|(x) &\le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t_n-s}}e^{\frac{3}{8}t_n+\frac{|\log(x)|}{2}} \nonumber \\
    &\le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}. \label{eq:In2}
\end{align}
Furthermore, notice that
\begin{equation*}
    P_sq(t,x)-q(t,x)=\int_0^s G P_\tau q(t,x) \, d\tau=\int_0^s  P_\tau G q(t,x) \, d\tau
\end{equation*}
where we used Item $(3)$ of Lemma \ref{lem:BSuniqueness} since $q(t,\cdot), \partial_x q(t,\cdot)$ and $Gq(t,\cdot)$ belong to $\operatorname{\mathcal{C}}_0$. In particular, recall that, by (\ref{eq:est3q}), that $Gq(t,\cdot) \in \operatorname{\mathcal{C}}_0(1/2)$ and
\begin{equation*}
    [Gq(t,\cdot)]_{\frac{1}{2}} \le \sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}.
\end{equation*}
Hence, by Item $(5)$ of Lemma \ref{lem:BSuniqueness} we get, since $\tau \le s \le t$
\begin{align*}
    |P_\tau Gq(t,x)| &\le 2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}\tau +\frac{|\log(x)|}{2}}\\
    &\le 2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}
\end{align*}
and then
\begin{equation}\label{eq:In3}
    |P_sq(t,x)-q(t,x)| \le 2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}s
\end{equation}
Analogously,
\begin{equation}\label{eq:In4}
    |P_sq(t_n,x)-q(t_n,x)| \le 2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}s.
\end{equation}
Combining (\ref{eq:In1}), (\ref{eq:In2}), (\ref{eq:In3}) and (\ref{eq:In4}) with (\ref{eq:In0}) we have
\begin{align*}
\begin{split}
    |P_sq(t-s,x)&-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)|\\
    & \le \frac{4\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t-s}}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}+4\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}s.
    \end{split}
\end{align*}
Integrating the latter against $s^{-1-\alpha}$ we get
\begin{align*}
\begin{split}
    \int_0^t |P_sq(t-s,x)&-q(t,x)-P_sq(t_n-s,x)+q(t_n,x)|s^{-1-\alpha}\, ds\\
    & \le \frac{4\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{K}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}\int_0^t (t-s)^{-\frac{1}{2}}s^{-\alpha}\, ds \\
    &\qquad +4\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}\int_0^t s^{-\alpha}\, ds\\
    &=\frac{4\Gamma\left(\alpha+\frac{1}{2}\right)\Gamma(1-\alpha)}{ \Gamma(\alpha)\Gamma\left(\frac{3}{2}-\alpha\right)}\sqrt{\frac{K}{\pi}}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}t^{\frac{1}{2}-\alpha}\\
    &\qquad +4\sqrt{\frac{K}{2}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi (1-\alpha)\Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}t^{\frac{1}{2}-\alpha}
    \end{split}
\end{align*}
where we also used \cite[Lemma 1.11]{ascione2023fractional}. Hence, we can use the dominated convergence theorem to guarantee that
\begin{equation*}
    \lim_{n \to \infty}I_n(x)=0.
\end{equation*}
Next, we move to $J_n(x)$. We have, arguing as before and recalling that this time $s \in [t_n,t]$,
\begin{align*}
    |P_sq(t_n-s,x)-q(t_n,x)| &\le |P_sq(t_n-s,x)-P_s q(t_n,x)|+|P_sq(t_n,x)-q(t_n,x)|\\
    &\le P_s|q(t_n-s,\cdot)-q(t_n,\cdot)|+|P_sq(t_n,x)-q(t_n,x)|\\
    &\le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)s}{\pi \Gamma(\alpha)}\sqrt{\frac{K}{t_n-s}}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}+2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}s.
\end{align*}
Hence,
\begin{align*}
   & J_n(x)\notag \\ &\le \frac{2\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{K}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}\int_{t}^{t_n} (t_n-s)^{-\frac{1}{2}}s^{-\alpha}\, ds+2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi \Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}\int_{t}^{t_n}s^{-\alpha}ds\\
    &=\frac{2\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{K}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}\int_{0}^{t_n-t} w^{-\frac{1}{2}}(t_n-w)^{-\alpha}\, dw+2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi (1-\alpha)\Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}(t_n^{1-\alpha}-t^{1-\alpha})\\
    &=\frac{2\Gamma\left(\alpha+\frac{1}{2}\right)}{\pi \Gamma(\alpha)}\sqrt{K}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}t_n^{\frac{1}{2}-\alpha}\int_{0}^{1-\frac{t}{t_n}} z^{-\frac{1}{2}}(1-z)^{-\alpha}\, dz+2\sqrt{\frac{K}{2t}}\frac{\Gamma\left(\alpha-\frac{1}{2}\right)}{2\pi (1-\alpha)\Gamma(\alpha)}e^{\frac{3}{8}t_1+\frac{|\log(x)|}{2}}(t_n^{1-\alpha}-t^{1-\alpha}).
\end{align*}
Hence, taking the limit as $n \to \infty$, we get
\begin{equation*}
    \lim_{n \to \infty}J_n(x)=0.
\end{equation*}
{Combined with the fact that also the remaining terms converge to 0 as $n \to \infty$,} this finally shows that
\begin{equation*}
    \lim_{n \to \infty}(\partial_t-G)^\alpha q(t_n,x)=(\partial_t-G)^\alpha q(t,x).
\end{equation*}
Now we prove that $\mathcal{I}_x = \varnothing$ for all $x>0$. Indeed, fix $x>0$ and assume that $\mathcal{I}_x \not = \varnothing$. Let $t \in \mathcal{I}_x$ and consider an interval of the form $[t,t+\delta]$ for some $\delta>0$. Since $|\mathcal{I}_x \cap [t,t+\delta]|=0$, we know that there exists a sequence $t_n \downarrow t$ such that $t_n \not \in \mathcal{I}_x$ for all $n \in \operatorname{\mathbb{N}}$. For such a sequence, we know that
\begin{equation*}
    (\partial_t-G)^{\alpha}q(t_n,x)=\frac{t_n^{-\alpha}}{\Gamma(1-\alpha)}q(0,x).
\end{equation*}
Taking the limit as $n \to \infty$ we get
\begin{equation*}
    (\partial_t-G)^{\alpha}q(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q(0,x)
\end{equation*}
that is absurd. Hence $\mathcal{I}_x=\varnothing$ and thus we get that
\begin{equation}
    (\partial_t-G)^{\alpha}q(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q(0,x), \ \qquad  \forall t,x>0.
\end{equation}
Finally, we notice that $q \in \operatorname{\mathcal{C}}_{0,{\rm loc}}(\operatorname{\mathbb{R}}_0^+)$ by Proposition \ref{prop:regq}.

\label{lem:estubeta}
    For all $\beta \ge 0$ and $t,x>0$ we have:
    \begin{align}
    \partial_x u_\beta(t,x)&=\beta e^{\frac{\beta(\beta-1)}{2}t+(\beta-1)\log(x)}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}-\frac{\log(x)}{\sqrt{t}}\right) \nonumber\\
    &\qquad -\beta e^{\frac{\beta(\beta+1)}{2}t-(\beta+1)\log(x)}\Phi\left(-\left(\beta+\frac{1}{2}\right)\sqrt{t}+\frac{\log(x)}{\sqrt{t}}\right) \label{eq:derub1}\\
    \partial^2_x u_\beta(t,x)&=\beta(\beta-1) e^{\frac{\beta(\beta-1)}{2}t+(\beta-2)\log(x)}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}-\frac{\log(x)}{\sqrt{t}}\right) \nonumber\\
    &\qquad +\beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}t-(\beta+2)\log(x)}\Phi\left(-\left(\beta+\frac{1}{2}\right)\sqrt{t}+\frac{\log(x)}{\sqrt{t}}\right)\nonumber \\
    &\qquad -\sqrt{\frac{2 \beta^2}{\pi t}}e^{-\frac{t}{8}-\frac{3}{2}\log(x)-\frac{\log^2(x)}{2t}}\label{eq:derub2}\\
    \partial_t u_\beta(t,x)&=Gu_\beta(t,x)=\frac{\beta(\beta-1)}{2} e^{\frac{\beta(\beta-1)}{2}t+\beta\log(x)}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}-\frac{\log(x)}{\sqrt{t}}\right) \nonumber\\
    &\qquad +\frac{\beta(\beta+1)}{2} e^{\frac{\beta(\beta+1)}{2}t-\beta\log(x)}\Phi\left(-\left(\beta+\frac{1}{2}\right)\sqrt{t}+\frac{\log(x)}{\sqrt{t}}\right)\nonumber \\
    &\qquad -\frac{\beta}{\sqrt{2\pi t}}e^{-\frac{t}{8}+\frac{\log(x)}{2}-\frac{\log^2(x)}{2t}}\label{eq:derub3}.
    \end{align}
In particular,
\begin{align}
|u_\beta(t,x)| &\le 2e^{\frac{\beta(\beta+1)}{2}t+\beta|\log(x)|} \label{eq:derub3.5}\\
|\partial_x u_\beta(t,x)| &\le 2 \beta e^{\frac{\beta(\beta+1)}{2}t+(\beta+1)|\log(x)|} \label{eq:derub4}\\
|\partial^2_x u_\beta(t,x)| &\le 2 \beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}t+(\beta+2)|\log(x)|}+\frac{\beta \sqrt{2}}{\sqrt{\pi t}}e^{\frac{3}{2}|\log(x)|} \label{eq:derub5}\\
|\partial_t u_\beta(t,x)|&=|G u_\beta(t,x)| \le \beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}t+\beta|\log(x)|}+\frac{\beta}{\sqrt{2\pi t}}e^{\frac{|\log(x)|}{2}}. \label{eq:derub6}
\end{align}

\label{prop:qbetatimereg}
Let ${\phi(\lambda)}=\lambda^\alpha$ for some $\alpha \in (0,1)$ and $\beta \ge 0$. Then for all $x>0$ the function $q_\beta(\cdot,x)$ belongs to ${\rm AC}(\operatorname{\mathbb{R}}_0^+)$ and its a.e. derivative $\partial_tq_\beta(\cdot,x)$ satisfies
\begin{equation}\label{eq:qbetaderest1}
    |\partial_t q_\beta(t,x)| \le \alpha\beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}(t+1)+\beta|\log(x)|}+\frac{2\beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\pi\sqrt{t}\Gamma(\alpha)}e^{\frac{|\log(x)|}{2}}.
\end{equation}
In particular, for all $t,x>0$
\begin{equation*}
    \frac{\alpha}{\Gamma(1-\alpha)}\int_0^t|P_sq_\beta(t-s,x)-P_sq_\beta(t,x)|s^{-1-\alpha}\, ds <\infty
\end{equation*}
and for all $x>0$ and $\lambda>\max\left\{\beta(\beta+1), \frac{3}{4}\right\}$
\begin{equation}\label{eq:LaptransPsdiff}
    \frac{\alpha}{\Gamma(1-\alpha)}\int_0^{+\infty}\int_0^te^{-\lambda t}|P_sq_\beta(t-s,x)-P_sq_\beta(t,x)|s^{-1-\alpha}\, ds\, dt <\infty.
\end{equation}

Arguing as in Proposition \ref{prop:ACqstar}, let $t>0$ and $h \in \left(-\frac{t}{2},1\right)$. We have
\begin{equation}\label{eq:incratiob}
    \left|\frac{q_\beta(t+h,x)-q_\beta(t,x)}{h}\right| \le \int_0^1\left|\frac{u_\beta(st+sh,x)-u_\beta(st,x)}{sh}\right|\frac{s^{\alpha}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)}\, ds.
\end{equation}
By Lagrange's theorem we know that there exists $\xi \in [\min\{ts,ts+hs\}, \max\{ts,ts+hs\}] \subseteq \left[\frac{ts}{2},(t+1)s\right] $ such that
\begin{align*}
\left|\frac{u_\beta(st+sh,x)-u_\beta(st,x)}{sh}\right|&=|\partial_t u_\beta(\xi,x)| \\
&\le \beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}\xi+\beta|\log(x)|}+\frac{\beta}{\sqrt{2\pi \xi}}e^{\frac{|\log(x)|}{2}} \\
&\le \beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}(t+1)s+\beta|\log(x)|}+\frac{\beta}{\sqrt{\pi ts}}e^{\frac{|\log(x)|}{2}},
\end{align*}
where we used (\ref{eq:derub6}). Using this bound into (\ref{eq:incratiob}) we get
\begin{align*}
    &\left|\frac{q_\beta(t+h,x)-q_\beta(t,x)}{h}\right| \\
    &\qquad \le \beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}(t+1)+\beta|\log(x)|}\int_0^1\frac{s^{\alpha}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)}\, ds\\
    &\qquad \qquad +\frac{\beta}{\sqrt{\pi t}}e^{\frac{|\log(x)|}{2}}\int_0^1\frac{s^{\alpha-\frac{1}{2}}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)}\, ds\\
    &\qquad =\alpha\beta(\beta+1) e^{\frac{\beta(\beta+1)}{2}(t+1)+\beta|\log(x)|}+\frac{2\beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\pi\sqrt{t}\Gamma(\alpha)}e^{\frac{|\log(x)|}{2}}.
\end{align*}
Arguing as in Proposition \ref{prop:AC}, this implies that $q_\beta(\cdot,x)$ belongs to ${\rm AC}(\operatorname{\mathbb{R}}_0^+)$ and that its a.e. derivative $\partial_t q_\beta(t,x)$ satisfies (\ref{eq:qbetaderest1}). 

Next, observe that
\begin{align*}
    |q_\beta(t-s,x)-q_\beta(t,x)| &\le \int_0^s |\partial_t q(t-\tau,x)|\, d\tau\\
    &\le \alpha\beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}(t+1)+\beta|\log(x)|}s+\frac{2s\beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\pi\sqrt{t-s}\Gamma(\alpha)}e^{\frac{|\log(x)|}{2}}.
\end{align*}
Setting $\widetilde{\beta}=\max\left\{\frac{1}{2},\beta\right\}$, we have that $|q_\beta(t-s,\cdot)-q_\beta(t,\cdot)| \in \operatorname{\mathcal{C}}_0(\widetilde{\beta})$ with
\begin{align*}
    [q_\beta(t-s,\cdot)-q_\beta(t,\cdot)]_{\widetilde{\beta}} \le \alpha\beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}(t+1)}s+\frac{2s\beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\pi\sqrt{t-s}\Gamma(\alpha)}
\end{align*}
and then, by Item $(5)$ of Lemma \ref{lem:BSuniqueness}
\begin{multline}\label{eq:estPsqbeta}
    P_s|q_\beta(t-s,\cdot)-q_\beta(t,\cdot)| \\ \le \left(2\alpha\beta(\beta+1)e^{\widetilde{\beta}(\widetilde{\beta}+1)(t+1)}s+\frac{4s\beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\pi\sqrt{t-s}\Gamma(\alpha)}e^{\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}t}\right)e^{\widetilde{\beta}|\log(x)|}.
\end{multline}
Thus we have
\begin{multline*}
    \frac{\alpha}{\Gamma(1-\alpha)}\int_0^t|P_sq_\beta(t-s,x)-P_sq_\beta(t,x)| s^{-1-\alpha}\, ds \\
    \le \left(\frac{2\alpha^2\beta(\beta+1)}{\Gamma(2-\alpha)}e^{\widetilde{\beta}(\widetilde{\beta}+1)(t+1)}t^{1-\alpha}+\frac{4\alpha \beta\Gamma\left(\frac{1}{2}+\alpha\right)}{\sqrt{\pi}\Gamma(\alpha)\Gamma\left(\frac{3}{2}-\alpha\right)}e^{\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}t}t^{\frac{1}{2}-\alpha}\right)e^{\widetilde{\beta}|\log(x)|}
\end{multline*}
that also implies (\ref{eq:LaptransPsdiff}) with $\lambda>\widetilde{\beta}(\widetilde{\beta}+1)$.

\label{prop:qbetareg2}
   For all $t,x>0$, we have
    \begin{equation}\label{eq:derinside}
        \partial_x q_\beta(t,x)=\frac{1}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^1 \partial_x u_\beta(t\tau,x)\tau^{\alpha-1}(1-\tau)^{-\alpha}d\tau.
    \end{equation}
    Furthermore, $q_\beta \in \operatorname{\mathcal{C}}_0(\beta)$ and $\partial_x q_\beta \in \operatorname{\mathcal{C}}_0(\beta+1)$, with
    \begin{align}
        [q_\beta(t,\cdot)]_\beta \le 2e^{\frac{\beta(\beta+1)}{2}t} \label{eq:qbetaest1}\\
        [\partial_xq_\beta(t,\cdot)]_\beta \le 2\beta e^{\frac{\beta(\beta+1)}{2}t}. \label{eq:qbetaest2}
    \end{align}

\label{prop:qbetareg3}
    Let $\alpha \in \left(\frac{1}{2},1\right)$ and $\beta \ge 0$. Then, for all $t,x>0$, we have
    \begin{align}\label{eq:derinside2}
        \partial^2_x q_\beta(t,x)=\frac{1}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^1 \partial^2_x u_\beta(t\tau,x)\tau^{\alpha-1}(1-\tau)^{-\alpha}d\tau.\\
        G q_\beta(t,x)=\frac{1}{\Gamma(\alpha)\Gamma(1-\alpha)}\int_0^1 G u_\beta(t\tau,x)\tau^{\alpha-1}(1-\tau)^{-\alpha}d\tau. \label{eq:opinside}
    \end{align}
    Moreover, $Gq_\beta \in \operatorname{\mathcal{C}}_0(\widetilde{\beta})$ with $\widetilde{\beta}=\max\left\{\beta, \frac{1}{2}\right\}$ and
    \begin{align}
        [Gq_\beta(t,\cdot)]_{\widetilde{\beta}} \le \beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}t}+\frac{\beta\Gamma\left(\alpha-\frac{1}{2}\right)\Gamma(1-\alpha)}{\pi\sqrt{2t}}.
        \label{eq:qbetaest3}
    \end{align}
    As a consequence, for all $t,x>0$,
    \begin{equation*}
        \frac{\alpha}{\Gamma(1-\alpha)}\int_0^t |P_sq(t,x)-q(t,x)|s^{-1-\alpha}\, ds < \infty,
    \end{equation*}
    and for all $x>0$ and $\lambda>\widetilde{\beta}(\widetilde{\beta}+1)$,
    \begin{equation}\label{eq:LapestGqbeta1}
        \frac{\alpha}{\Gamma(1-\alpha)}\int_0^\infty \int_0^t e^{-\lambda t}|P_sq(t,x)-q(t,x)|s^{-1-\alpha}\, ds\, dt < \infty.
    \end{equation}

Fix $x,t>0$ and let $0<a<x<b$. For $y \in [a,b]$ and $\tau \in [0,1]$, by (\ref{eq:derub5}), we have
    \begin{equation*}
        |\partial_x^2 u_\beta(t\tau,y)| \le 2\beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}t+(\beta+2)M}+\frac{\beta \sqrt{2}}{\sqrt{\pi t\tau}}e^{\frac{3M}{2}},
    \end{equation*}
    where $M=\max\{|\log(a)|, |\log(b)|\}$. Notice that the right-hand side is integrable against $g_H(\tau,1)$. Indeed,
    \begin{align*}
        \int_0^1 &\left(2\beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}t+(\beta+2)M}+\frac{\beta}{\sqrt{2\pi t\tau}}e^{\frac{M}{2}}\right)\tau^{\alpha-1}(1-\tau)^{-\alpha}\, d\tau\\
        &=2\beta(\beta+1)e^{\frac{\beta(\beta+1)}{2}t+(\beta+2)M}+\frac{\beta\Gamma\left(\alpha-\frac{1}{2}\right)\Gamma(1-\alpha)\sqrt{2}}{\pi\sqrt{t}}e^{\frac{3M}{2}}.
    \end{align*}
    Hence, an application of the dominated convergence theorem to (\ref{eq:derinside}) leads to (\ref{eq:derinside2}). Furthermore, multiplying both sides of (\ref{eq:derinside2}) by $\frac{x^2}{2}$ we get (\ref{eq:opinside}) and (\ref{eq:qbetaest3}) follows by (\ref{eq:opinside}) and (\ref{eq:derub6}).

    Now observe that by Proposition \ref{prop:qbetareg3} we know that $q_\beta(t,\cdot), \partial_x q_\beta(t,\cdot) \in \operatorname{\mathcal{C}}_0$, while we also proved that $G q_\beta(t,\cdot) \in \operatorname{\mathcal{C}}_0$. Hence we can write
    \begin{equation*}
    P_sq_\beta(t,x)-q_\beta(t,x)=\int_0^s GP_\tau q_\beta(t,x)\, d\tau=\int_0^s P_\tau Gq_\beta(t,x)\, d\tau.
    \end{equation*}
    Furthermore, by (\ref{eq:qbetaest3}) and Item $(5)$ of Lemma \ref{lem:BSuniqueness} we get for $\tau \in [0,s] \subseteq [0,t]$
    \begin{align}
        P_\tau |Gq_\beta(t,\cdot)| \le \left(\beta(\beta+1)e^{\widetilde{\beta}(\widetilde{\beta}+1)t}+\frac{\beta\Gamma\left(\alpha-\frac{1}{2}\right)\Gamma(1-\alpha)}{\pi\sqrt{2t}}e^{\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}t}\right)e^{\widetilde{\beta}|\log(x)|}.
        \label{eq:PtauGbetaest}
    \end{align}
    Thus, we have
    \begin{multline}
        |P_sq_\beta(t,x)-q(t,x)| \\ \le \left(\beta(\beta+1)e^{\widetilde{\beta}(\widetilde{\beta}+1)t}+\frac{\beta\Gamma\left(\alpha-\frac{1}{2}\right)\Gamma(1-\alpha)}{\pi\sqrt{2t}}e^{\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}t}\right)se^{\widetilde{\beta}|\log(x)|}.
        \label{eq:Ptaudiffest2}
    \end{multline}
    and then
    \begin{multline*}
        \frac{\alpha}{\Gamma(1-\alpha)}\int_0^t |P_sq_\beta(t,x)-q(t,x)|s^{-1-\alpha}\, ds \\
        \le \frac{\alpha}{\Gamma(2-\alpha)}\left(\beta(\beta+1)e^{\widetilde{\beta}(\widetilde{\beta}+1)t}+\frac{\beta\Gamma\left(\alpha-\frac{1}{2}\right)\Gamma(1-\alpha)}{\pi\sqrt{2t}}e^{\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}t}\right)t^{1-\alpha}e^{\widetilde{\beta}|\log(x)|}.
    \end{multline*}
    Eventually, the latter inequality implies (\ref{eq:LapestGqbeta1}) for $\lambda>\widetilde{\beta}(\widetilde{\beta}+1)$.

\label{prop:qbetareg4}
Let $\alpha \in (0,1)$ and $\beta \ge 0$. Then, for all $\lambda>\frac{\beta(\beta+1)}{2}$ and $x>0$ we have
\begin{equation*}
    \frac{1}{\Gamma(1-\alpha)}\int_0^\infty t^{-\alpha}e^{-\lambda t}|q_\beta(t,x)|\, dt<\infty.
\end{equation*}

By (\ref{eq:qbetaest1}) we have
\begin{align*}
    \frac{1}{\Gamma(1-\alpha)}\int_0^\infty t^{-\alpha}e^{-\lambda t}|q_\beta(t,x)|\, dt &\le \frac{2e^{\beta|\log(x)|}}{\Gamma(1-\alpha)}\int_0^\infty t^{-\alpha}e^{-\left(\lambda-\frac{\beta(\beta+1)}{2}\right)t}\, dt\\
    &=2e^{\beta|\log(x)|}\left(\lambda-\frac{\beta(\beta+1)}{2}\right)^{\alpha-1}.
\end{align*}

\label{prop:testsol}
    Let $\alpha \in \left(\frac{1}{2},1\right)$ and $\beta \ge 0$. Then $q_\beta$ is a solution of
    \begin{equation}\label{eq:specialeq}
    \begin{cases}
    (\partial_t-G)^\alpha q_\beta(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q_\beta(0,x) & t,x>0 \\
    q_\beta(0,x)=e^{\beta|\log(x)|} & x>0.
    \end{cases}
    \end{equation}

First notice that $q_\beta(0,x)=u_\beta(0,x)=e^{\beta|\log(x)|}$. By Propositions \ref{prop:qbetatimereg}, \ref{prop:qbetareg3} and \ref{prop:qbetareg4} we know that $(\partial_t-G)^\alpha q_\beta(t,x)$ is well-defined for all $t,x>0$ and for fixed $x>0$ the function $(\partial_t-G)^\alpha q_\beta(\cdot,x)$ is Laplace transformable for $\lambda>\widetilde{\beta}(\widetilde{\beta}+1)$, where $\widetilde{\beta}=\max\left\{\beta,\frac{1}{2}\right\}$. Now we show that
\begin{equation}\label{eq:Laplaceequality}
    \int_0^\infty e^{-\lambda t}(\partial_t-G)^\alpha q_\beta(t,x)\, dt=\lambda^{\alpha-1}e^{\beta|\log(x)|}
\end{equation}
for $\lambda>\frac{1}{16}\left(\frac{1}{4}+\widetilde{\beta}(\widetilde{\beta}+1)\right)$. This is done exactly as in Proposition \ref{prop:qsolution}, the only difference being the bound we prove to use Fubini's theorem in (\ref{eq:preFub}). Precisely, recall that $f_\beta(x)=e^{\beta|\log(x)|}$ and set
\begin{equation*}
\overline{u}(t,x)=e^{-\frac{\log^2(x)}{2t}}f_{\widetilde{\beta}}(x)
\end{equation*}
and notice that, by (\ref{eq:derub3.5}) and (\ref{eq:derub6})
\begin{equation*}
    \left| (G-\lambda) u_{\beta} (w,y) \right| \le \left((\beta(\beta+1)+2\lambda)e^{\frac{\beta(\beta+1)}{2}w}f_{\widetilde{\beta}}(y)+\frac{\beta}{\sqrt{2\pi w}}\overline{u}(w,y)\right).
\end{equation*}
Hence, we have
\begin{align}
 &   \int_0^{+\infty}\int_0^{+\infty}\int_0^{+\infty} \int_0^s \tau^{\alpha-1}s^{-\alpha-1}e^{-\lambda (\tau+w)} \left| (G-\lambda) u_{\beta} (w,y) \right| p_{\rm GBM} (\tau, y;x) \, dw \, dy \, d\tau \, ds \notag \\
 & \le \int_0^{+\infty}\int_0^{+\infty}\int_0^{s} (\beta(\beta+1)+2\lambda)e^{\frac{\beta(\beta+1)}{2}w}\tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}u_{\widetilde{\beta}}(\tau,x) \, dw  \, d\tau \, ds \nonumber \\
 &\qquad +\int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \frac{\beta}{\sqrt{2\pi w}}\tau^{\alpha-1} s^{-\alpha-1}e^{-\lambda (\tau+w)}P_\tau \overline{u}(w,x) \, dw  \, d\tau \, ds \nonumber \\
 &=I_1+I_2.





 \label{Fubnew1}
 \end{align}
Concerning $I_1$, we have, by Item $(5)$ of Lemma \ref{lem:BSuniqueness}
 \begin{align*}
 I_1& \le 2(\beta(\beta+1)+2\lambda)\int_0^{+\infty}\int_0^{+\infty}\int_0^{s} e^{-\left(\lambda-\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}\right)(\tau+w)}\tau^{\alpha-1} s^{-\alpha-1} \, dw  \, d\tau \, ds\\
 &=\frac{4(\beta(\beta+1)+2\lambda)}{2\lambda-\widetilde{\beta}(\widetilde{\beta}+1)}\left(\int_0^{+\infty}\left(1-e^{-\left(\lambda-\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}\right)s}\right)s^{-\alpha-1}\, ds\right)\\
 &\qquad \times \left(\int_0^{+\infty}e^{-\left(\lambda-\frac{\widetilde{\beta}(\widetilde{\beta}+1)}{2}\right)\tau}\tau^{\alpha-1} \, d\tau\right)\\
 &=\frac{4(\beta(\beta+1)+2\lambda)\Gamma(1-\alpha)\Gamma(\alpha)}{2\lambda-\widetilde{\beta}(\widetilde{\beta}+1)}.
 \end{align*}
For $I_2$, we first need to evaluate $P_\tau \overline{u}(w,x)$. We have
\begin{align*}
    P_\tau \overline{u}(w,x)&=\int_0^{+\infty} e^{-\frac{\log^2(y)}{2w}+\widetilde{\beta}|\log(y)|-\frac{\tau}{8}-\frac{(\log(y)-\log(x))^2}{2\tau}}\sqrt{\frac{x}{y^3 2\pi \tau}}\, dy\\
    &=\sqrt{x}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}\int_0^{+\infty} e^{-\frac{\log^2(y)}{2w}-\frac{\log^2(y)}{2\tau}+\frac{\log(y)\log(x)}{\tau}+\widetilde{\beta}|\log(y)|}\frac{1}{\sqrt{y^3 2\pi \tau}}\, dy.
\end{align*}
Now let $z=\log(y)$ to achieve
\begin{align*}
    P_\tau \overline{u}(w,x)&=\sqrt{\frac{x}{2\pi \tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}\int_{-\infty}^{+\infty} e^{-\frac{z^2}{2w}-\frac{z^2}{2\tau}+\frac{\log(x)}{\tau}z-\frac{z}{2}+\widetilde{\beta}|z|}\, dz.
\end{align*}
Define
\begin{equation}
    \mathcal{H}(\tau,w)=\left(\frac{1}{w}+\frac{1}{\tau}\right)^{-1}
\end{equation}
so that
\begin{align*}
    P_\tau \overline{u}(w,x)&=\sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}\int_{-\infty}^{+\infty} \frac{1}{\sqrt{2\pi \mathcal{H}(\tau,w)}}e^{-\frac{z^2}{2\mathcal{H}(\tau,w)}+\left(\frac{\log(x)}{\tau}-\frac{1}{2}\right)z+\widetilde{\beta}|z|}\, dz\\
    &=\sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}\operatorname{\mathds{E}}^{(0,0)}[e^{\widetilde{\beta} |B(\mathcal{H}(\tau,w))|+\left(\frac{\log(x)}{\tau}-\frac{1}{2}\right)B(\mathcal{H}(\tau,w))}]\\
    &=\sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}e^{\frac{1}{2}\left(\widetilde{\beta}+\frac{\log(x)}{\tau}-\frac{1}{2}\right)^2\mathcal{H}(\tau,w)}\Phi\left(-\left(\widetilde{\beta}+\frac{\log(x)}{\tau}-\frac{1}{2}\right)\sqrt{t}\right)\\
    &\qquad + \sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2\tau}}e^{\frac{1}{2}\left(\widetilde{\beta}-\frac{\log(x)}{\tau}+\frac{1}{2}\right)^2\mathcal{H}(\tau,w)}\Phi\left(-\left(\widetilde{\beta}-\frac{\log(x)}{\tau}+\frac{1}{2}\right)\sqrt{t}\right)\\
    &=\sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2(\tau+w)}+A_1\mathcal{H}(\tau,w)+\left(\widetilde{\beta}-\frac{1}{2}\right)\frac{w}{\tau+w}\log(x)}\Phi\left(-A_2\sqrt{t}\right)\\
    &\qquad + \sqrt{\frac{x \mathcal{H}(\tau,w)}{\tau}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2(\tau+w)}+B_1\mathcal{H}(\tau,w)-\left(\widetilde{\beta}+\frac{1}{2}\right)\frac{w}{\tau+w}\log(x)}\Phi\left(-B_2\sqrt{t}\right),
\end{align*}
where
\begin{align*}
A_1=\frac{\widetilde{\beta}^2}{2}+\frac{1}{8}-\frac{\widetilde{\beta}}{2} && A_2=\widetilde{\beta}+\frac{\log(x)}{\tau}-\frac{1}{2}\\
B_1=\frac{\widetilde{\beta}^2}{2}+\frac{1}{8}+\frac{\widetilde{\beta}}{2} && B_2=\beta-\frac{\log(x)}{\tau}+\frac{1}{2}
\end{align*}
and we used Lemma \ref{lem:momgen}. Furthermore, we have
\begin{align*}
    \frac{\beta}{\sqrt{2\pi w}}P_\tau \overline{u}(w,x)&=\beta\sqrt{\frac{x}{2\pi(\tau+w)}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2(\tau+w)}+A_1\mathcal{H}(\tau,w)+\left(\widetilde{\beta}-\frac{1}{2}\right)\frac{w}{\tau+w}\log(x)}\Phi\left(-A_2\sqrt{t}\right)\\
    &\qquad +2\beta\sqrt{\frac{x}{2\pi(\tau+w)}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2(\tau+w)}+B_1\mathcal{H}(\tau,w)-\left(\widetilde{\beta}+\frac{1}{2}\right)\frac{w}{\tau+w}\log(x)}\Phi\left(-B_2\sqrt{t}\right)\\
    &\le \frac{\beta}{\sqrt{2\pi(\tau+w)}}e^{-\frac{\tau}{8}-\frac{\log^2(x)}{2(\tau+w)}+B_1\mathcal{H}(\tau,w)+\left(\widetilde{\beta}+1\right)|\log(x)|},
\end{align*}
where we used $B_1>A_1$ and $\frac{w}{\tau+w} \le 1$. Now recall that the function $r \in \operatorname{\mathbb{R}}^+ \mapsto \sqrt{r}e^{-\frac{\log^2(x)}{2r}} \in \operatorname{\mathbb{R}}^+$ admits as maximum point $r_\star=\log^{-2}(x)$, so that
\begin{align*}
    \frac{\beta}{\sqrt{2\pi w}}P_\tau \overline{u}(w,x)&\le \frac{\beta}{\sqrt{2\pi e}}|\log^{-1}(x)|e^{-\frac{\tau}{8}+B_1\mathcal{H}(\tau,w)+\left(\widetilde{\beta}+1\right)|\log(x)|}.
\end{align*}
Next, we observe that $2\mathcal{H}(\tau,w)$ is the harmonic mean of $\tau$ and $w$, hence, we can use the fact that the harmonic mean is smaller than or equal to the arithmetic mean to write
\begin{equation*}
    \mathcal{H}(\tau,w) \le \frac{\tau+w}{4}
\end{equation*}
and thus we get 
\begin{align*}
    \frac{\beta}{\sqrt{2\pi w}}P_\tau \overline{u}(w,x)&\le \frac{\beta}{\sqrt{2\pi e}}|\log^{-1}(x)|e^{\frac{B_1}{4}(\tau+w)+\left(\widetilde{\beta}+1\right)|\log(x)|}.
\end{align*}
Now we can go back to $I_2$ to get 
\begin{align*}
    I_2 &\le \frac{\beta}{\sqrt{2\pi e}}|\log^{-1}(x)|e^{\left(\widetilde{\beta}+1\right)|\log(x)|}\int_0^{+\infty}\int_0^{+\infty}\int_0^{s} \tau^{\alpha-1} s^{-\alpha-1}e^{-\left(\lambda-\frac{B_1}{4}\right) (\tau+w)} \, dw  \, d\tau \, ds\\
    &=\frac{\beta}{\left(\lambda-\frac{B_1}{4}\right)\sqrt{2\pi e}}|\log^{-1}(x)|e^{\left(\widetilde{\beta}+1\right)|\log(x)|}\left(\int_0^{+\infty}s^{-\alpha-1}\left(1-e^{-\left(\lambda-\frac{B_1}{4}\right)s}\right)\, ds\right)\\
    &\qquad \times \left(\int_0^{+\infty} \tau^{\alpha-1}e^{-\left(\lambda-\frac{B_1}{4}\right)\tau} \, d\tau \right)\\
    &=\frac{\beta\Gamma(1-\alpha)\Gamma(\alpha)}{\left(\lambda-\frac{B_1}{4}\right)\sqrt{2\pi e}}|\log^{-1}(x)|e^{\left(\widetilde{\beta}+1\right)|\log(x)|}.
\end{align*}
 Once we have (\ref{eq:Laplaceequality}), we know that for all $x>0$ there exists $\mathcal{I}_x \subset \operatorname{\mathbb{R}}^+$ such that $|\mathcal{I}_x|=0$ and for all $t \in \operatorname{\mathbb{R}}^+ \setminus \mathcal{I}_x$ we have
\begin{equation}\label{eq:equalitysol}
    (\partial_t-G)^\alpha q_\beta(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q_\beta(0,x).
\end{equation}
Analogously to what we did in Proposition \ref{prop:qsolution}, we need to prove that $\mathcal{I}_x=\varnothing$. First, notice that a simple application of the dominated convergence theorem to (\ref{eq:qbeta}), justified by (\ref{eq:derub3.5}), shows that $q_\beta$ is continuous. Furthermore, arguing exactly as in Proposition \ref{prop:qsolution}, by means of the estimates (\ref{eq:estPsqbeta}) and (\ref{eq:Ptaudiffest2}), one can show that if $t_n \downarrow t$, then $(\partial_t-G)^\alpha q_\beta(t_n,x) \to (\partial_t-G)^\alpha q_\beta(t,x)$. This shows, with the same argument as in Proposition \ref{prop:qsolution}, that $\mathcal{I}_x=\varnothing$ for all $x>0$ and then $q_\beta$ is solution of (\ref{eq:specialeq}).

\label{prop:lobound}
    Let $\alpha \in (0,1)$ and $\beta \ge 0$. Then there exists a non-increasing function $C_\beta:\operatorname{\mathbb{R}}^+ \to \operatorname{\mathbb{R}}$ with $C_\beta(t)>0$ for all $t>0$ and such that
    \begin{equation*}
        q_\beta(t,x) \ge C_\beta(t)e^{\beta|\log(x)|}.
    \end{equation*}

First of all, let us observe that if $x \ge 1$ then $\log(x) \ge 0$ and we have
    \begin{equation*}
    u_\beta(t,x) \ge e^{\beta \log(x)+\frac{\beta(\beta+1)}{2}t}\Phi\left(-\left(\beta+\frac{1}{2}\right)\sqrt{t}\right) \ge e^{\beta \log(x)+\frac{\beta(\beta-1)}{2}t}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}\right).
    \end{equation*}
    If instead $x \in (0,1]$, then $\log(x) \le 0$ and
    \begin{equation*}
    u_\beta(t,x) \ge e^{-\beta \log(x)+\frac{\beta(\beta-1)}{2}t}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}\right).
    \end{equation*}
    Hence, in general, we have
    \begin{equation*}
    u_\beta(t,x) \ge e^{\beta |\log(x)|+\frac{\beta(\beta-1)}{2}t}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}\right).
    \end{equation*}
    Next, by (\ref{eq:qbeta}), we get
    \begin{align*}
        q_\beta(t,x)& \ge e^{\beta|\log(x)|}\int_0^1e^{\frac{\beta(\beta-1)}{2}ts}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{ts}\right)\frac{s^{\alpha-1}(1-s)^{-\alpha}}{\Gamma(\alpha)\Gamma(1-\alpha)} \\
        &\ge \begin{cases} \frac{ e^{\beta|\log(x)|+\frac{\beta(\beta-1)}{2}t}}{2} & \beta \le \frac{1}{2} \\ e^{\beta|\log(x)|+\frac{\beta(\beta-1)}{2}t}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}\right) & \beta \in \left(\frac{1}{2},1\right]\\
        e^{\beta|\log(x)|}\Phi\left(-\left(\beta-\frac{1}{2}\right)\sqrt{t}\right) & \beta > 1,
        \end{cases}
    \end{align*}
    that ends the proof.

\label{prop:uniquenessBSnonloc}
    Let $\alpha \in \left(\frac{1}{2},1\right)$ and $f \in \operatorname{\mathcal{C}}_0$. Then, the equation
    \begin{equation}\label{eq:BSnonlocgen}
    \begin{cases}
    (\partial_t-G)^\alpha q_f(t,x)=\frac{t^{-\alpha}}{\Gamma(1-\alpha)}q_f(0,x) & t,x>0 \\
    q_f(0,x)=f(x) & x>0\\
    q_f \in \operatorname{\mathcal{C}}_{0,{\rm loc}}(\operatorname{\mathbb{R}}_0^+)
    \end{cases}
    \end{equation}
    at most has one solution.

Since the equation is linear, it is sufficient to verify that if $f \equiv 0$ then the solution $q_f \equiv 0$. Fix $T>0$ and recall that since $q_f \in \operatorname{\mathcal{C}}_{0,{\rm loc}}(\operatorname{\mathbb{R}}_0^+)$ then
    \begin{equation*}
        |q_f(t,x)| \le C_Te^{\beta_T|\log(x)|}.
    \end{equation*}
    For simplicity, set $C_T=C$ and $\beta_T:=\beta_0$. Now, for any $A \ge 1$ and $\beta>\beta_0$, consider the function
    \begin{equation*}
        w_\beta(t,x;A):=\frac{C}{C_\beta(T)}e^{(\beta_0-\beta)|\log(A)|}q_\beta(t,x).
    \end{equation*}
    Notice that $w_\beta(0,x;A)>0=q_f(0,x)$ for all $x>0$. Next, by Proposition \ref{prop:lobound} we have that, for $t \in (0,T]$,
    \begin{equation*}
        w_\beta(t,x;A) \ge \frac{C_\beta(t)}{C_\beta(T)}Ce^{(\beta_0-\beta)|\log(A)|+\beta|\log(x)|} \ge Ce^{(\beta_0-\beta)|\log(A)|+\beta|\log(x)|}.
    \end{equation*}
    If $x \not \in \left[A^{-1},A\right]$ then $|\log(x)| \ge |\log(A)|$ and we have
    \begin{equation*}
        w_\beta(t,x;A) \ge Ce^{\beta_0|\log(A)|} \ge |q_f(t,x)|.
    \end{equation*}
    This shows that for all $x \not \in \left[A^{-1},A\right]$ and $t \in [0,T]$
    \begin{equation}\label{eq:inequalitytoextend}
        w_\beta(t,x;A)+q_f(t,x) \le 0 \le w_\beta(t,x;A)-q_f(t,x).
    \end{equation}
    We want to show that this inequality holds for all $x>0$. To do this, assume by contradiction that there exists a point $(t_\star,x_\star) \in [0,T] \times \operatorname{\mathbb{R}}^+$ such that 
    \begin{equation*}
    w_\beta(t_\star,x_\star;A)-q_\beta(t_\star,x_\star)<0.
    \end{equation*}
    It must hold $x_\star \in [A^{-1},A]$. Furthermore, since all the involved functions are continuous, we can assume without loss of generality that
    \begin{equation*}
        w_\beta(t_\star,x_\star;A)-q_f(t_\star,x_\star)=\min_{(t,x) \in [0,T] \times [A^{-1},A]}(w_\beta(t,x;A)-q_f(t,x)).
    \end{equation*}
    First of all, notice that for all $x \in \operatorname{\mathbb{R}}^+$
    \begin{equation*}
        w_\beta(t_\star,x_\star;A)-q_f(t_\star,x_\star)<0<w_\beta(0,x;A)-q_f(0,x).
    \end{equation*}
    Moreover, using (\ref{eq:inequalitytoextend}) for $x \not \in [A^{-1},A]$ {and} the definition of $(t_\star,x_\star)$, if $x \in [A^{-1},A]$, we get
    \begin{equation*}
        w_\beta(t_\star,x_\star;A)-q_f(t_\star,x_\star) \le w_\beta(t,x;A)-q_f(t,x)
    \end{equation*}
    for all $t \in [0,T]$ and $x>0$. By Proposition \ref{prop:maxprin} we must have
    \begin{equation*}
    -(\partial_t-G)^\alpha (w_\beta(\cdot,\cdot;A)-q_f(\cdot,\cdot))(x_\star,t_\star)+\frac{t_\star^{-\alpha}}{\Gamma(1-\alpha)}w_\beta(0,x_\star;A)>0.
    \end{equation*}
    However, by Proposition \ref{prop:testsol} we know that, up to a multiplicative constant, $w_\beta(\cdot,\cdot;A)$ solves (\ref{eq:specialeq}), while $q_f$ solves (\ref{eq:BSnonlocgen}), hence
    \begin{equation*}
    -(\partial_t-G)^\alpha (w_\beta(\cdot,\cdot;A)-q_f(\cdot,\cdot))(x_\star,t_\star)+\frac{t_\star^{-\alpha}}{\Gamma(1-\alpha)}w_\beta(0,x_\star;A)=0,
    \end{equation*}
    {which is a contradiction}. Thus, we find
    \begin{equation*}
        w_\beta(t,x;A)-q_f(t,x) \ge 0, \ \forall x>0, \ t \in [0,T]
    \end{equation*}
    With a similar argument one can prove that
    \begin{equation*}
        w_\beta(t,x;A)+q_f(t,x) \le 0, \ \forall x>0, \ t \in [0,T]
    \end{equation*}
    and then, since (\ref{eq:inequalitytoextend}) holds for all $x>0$ and $t \in [0,T]$, we have
    \begin{equation*}
    |q_f(t,x)| \le w_\beta(t,x;A)=\frac{C}{C_\beta(T)}e^{(\beta_0-\beta)|\log(A)|}q_\beta(t,x)
    \end{equation*}
    taking the limit as $A \to \infty$ we get that $|q_f(t,x)|=0$ for all $x>0$ and $t \in [0,T]$. Since $T>0$ is arbitrary, we end the proof.

\label{prop:generator1}
    Let ${\phi(\lambda)}=\lambda^{\alpha}$ for some $\alpha \in (0,1)$. Then, on $f \in C_c^\infty(\operatorname{\mathbb{R}}\times \operatorname{\mathbb{R}}^+)$ the generator $A^\phi$ of $(B^\phi,{S})$ acts as follows:
    \begin{align*}
    A^\phi f(x,v)&=\int_{\operatorname{\mathbb{R}}}\int_{\operatorname{\mathbb{R}}}(f(x+h,s+v)-f(x,v)-h\partial_xf(x,v)\mathds{1}_{[-1,1]}(h))\mathcal{K}(dh;ds) \, dh,
\end{align*}
where $\mathcal{K}$ is defined in (\ref{eq:K}).

We already know by (\ref{prezzofinbsnonloca}) that $q_\star(T-t,x,0)=q(t,x)$. Furthermore, by Proposition \ref{prop:qsolution} we know that the function $q$ solves (\ref{eq:BSUnder}) and by Proposition \ref{prop:uniquenessBSnonloc} that it is actually the unique solution. We only need to prove (\ref{eq:possoj}). To do this, denote by $(\mathcal{Q}_t)_{t \ge 0}$ the transition semigroup of $(X_{\rm e}(t),\gamma(t))$ and observe that
\begin{align*}
q_\star(t,X(t),\gamma(t))&=\widetilde{Q}_{T-t}u(X(t),\gamma(t))\\
&=\widetilde{\operatorname{\mathds{E}}}^{(x,v)}[(X(T)-K)_+ \mid X(t), \gamma(t)]\\
&=\operatorname{\mathds{E}}^{(x,v)}[(e^{X_{\rm e}(T)-\frac{T-v-\gamma(T)}{2}}-K)_+ \mid X(t), \gamma(t)]\\
&=\mathcal{Q}_{T-t}g_{T,v}(X_{\rm e}(t),\gamma(t))=\mathcal{Q}_{T-t}g_{T,v}(\log(X(t)),\gamma(t)),
\end{align*}
where
\begin{equation*}
    g_{T,v}(x,w)=(e^{x-\frac{T-v-w}{2}}-K)_+.
\end{equation*}
By Proposition \ref{prop:generator1} and \cite[Theorem 4.1]{meerschaert2014semi}, we have, for $w>0$
\begin{equation*}
    \mathcal{Q}_{t}g(x,w)=g(x,w+t)\mathcal{K}_w(x;\operatorname{\mathbb{R}}^d \times [w+t,\infty))+ \int_{\operatorname{\mathbb{R}} \times [w,w+t)}\mathcal{Q}_{t+w-\tau}g(x+y,0)\mathcal{K}_w(d\tau,dy),
\end{equation*}
In our case, this becomes
\begin{multline}\label{eq:presubstitut}
    q_\star(t,x,w)=\mathcal{Q}_{T-t}g_{T,v}(\log(x),w)=g_{T,v}(\log(x),w+T-t)\mathcal{K}_w(x;\operatorname{\mathbb{R}}^d \times [w+T-t,\infty))\\
    +\int_{\operatorname{\mathbb{R}} \times [w,w+T-t)}\mathcal{Q}_{T-t+w-\tau}g_{T,v}(\log(x)+y,0)\mathcal{K}_w(d\tau,dy).
\end{multline}
{Now, we just have} to evaluate the inner term. We have, setting for {brevity} $\widetilde{x}=\log(x)+y+t-w+\tau-v$ and $\widetilde{t}=T-t+w-\tau$,
\begin{align*}
&\mathcal{Q}_{T-t+w-\tau}g_{T,v}(\log(x)+y,0)\\
&=\operatorname{\mathds{E}}^{(\log(x)+y,0)}\left[\left(\exp\left(X_{\rm e}(\widetilde{t})-\frac{T-v-\gamma(\widetilde{t})}{2}\right)-K\right)_+\right]\\
&=\operatorname{\mathds{E}}^{(\widetilde{x},0)}\left[\left(\exp\left(X_{\rm e}(\widetilde{t})-\frac{\widetilde{t}-\gamma(\widetilde{t})}{2}\right)-K\right)_+\right]\\
&=\operatorname{\mathds{E}}^{(\widetilde{x},0)}[(X(\widetilde{t})e^{-\frac{\widetilde{t}-\gamma(\widetilde{t})}{2}}-K)_+]=q(\widetilde{t},\widetilde{x}).



\end{align*}
Substituting the latter expression into (\ref{eq:presubstitut}) we get (\ref{eq:possoj}).

\label{lem:condexpprop}
Let $X,Y,Z$ be three random variables with values respectively in $E_X,E_Y,E_Z$. Assume that $Z$ is independent of both $X$ and $Y$. Then, for any bounded measurable function $F:E_X \times E_Z \to \operatorname{\mathbb{R}}$
\begin{equation*}
\operatorname{\mathds{E}}[F(X,Z)\mid X,Y]=\operatorname{\mathds{E}}[F(X,Z) \mid X]
\end{equation*}

First consider two sets $B_X \in \operatorname{\mathcal{E}}_X$ and $B_Z \in \operatorname{\mathcal{E}}_Z$. Then
    \begin{align*}
    \operatorname{\mathds{E}}\left[\mathds{1}_{B_X}(X)\mathds{1}_{B_Z}(Z) \mid X,Y\right]&=\mathds{1}_{B_X}(X)\operatorname{\mathds{E}}\left[\mathds{1}_{B_Z}(Z) \mid X,Y\right]\\
    &=\mathds{1}_{B_X}(X)\operatorname{\mathds{E}}\left[\mathds{1}_{B_Z}(Z)\right]\\
    &=\mathds{1}_{B_X}(X)\operatorname{\mathds{E}}\left[\mathds{1}_{B_Z}(Z) \mid X\right]\\
    &=\operatorname{\mathds{E}}\left[\mathds{1}_{B_X}(X)\mathds{1}_{B_Z}(Z) \mid X\right].
    \end{align*}
    Now fix $F \in \sigma(X,Y)$ and define for any $B \in \operatorname{\mathcal{E}}_X \otimes \operatorname{\mathcal{E}}_Z$
    \begin{equation*}
    \mu_F(B)=\operatorname{\mathds{E}}\left[\mathds{1}_F\operatorname{\mathds{E}}\left[\mathds{1}_{B}(X,Z)\mid X,Y\right]\right]
    \end{equation*}
    and
    \begin{equation*}
    \nu_F(B)=\operatorname{\mathds{E}}\left[\mathds{1}_F\operatorname{\mathds{E}}\left[\mathds{1}_{B}(X,Z)\mid X\right]\right].
    \end{equation*}
    Notice that on $B=B_X \times B_Z$ for some $B_X \in \operatorname{\mathcal{E}}_X$ and $B_Z \in \operatorname{\mathcal{E}}_Z$ it holds $\mu_F(B_X \times B_Z)=\nu_F(B_X \times B_Z)$. Since the sets of the form $B_X \times B_Z$ constitute a $\pi$-system generating $\operatorname{\mathcal{E}}_X \otimes \operatorname{\mathcal{E}}_Z$, this is enough to guarantee that $\mu_F=\nu_F$. Furthermore, since $F \in \sigma(X,Y)$ is arbitrary, this leads to
    \begin{equation*}
        \operatorname{\mathds{E}}\left[\mathds{1}_{B}(X,Z)\mid X,Y\right]=\operatorname{\mathds{E}}\left[\mathds{1}_{B}(X,Z)\mid X\right]
    \end{equation*}
    for all $B \in \operatorname{\mathcal{E}}_X \times \operatorname{\mathcal{E}}_Z$. Once this has been shown for indicator functions, a standard argument leads to the statement.
